Lemma bcmp_branch : forall ls rs : list byte, length ls = length rs ->
  bv_eqb (Z_to_bv 64 (zmemcmp (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs))) (Z_to_bv 64 0) = lzeqb (zbytes ls) (zbytes rs).
Proof.
  intros ls rs L. rewrite bv_eqb_Z. change (bv_unsigned (Z_to_bv 64 0)) with 0.
  change (zmemcmp (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs))
    with (F_memcmp.memcmp_model (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs)).
  pose proof (F_memcmp.memcmp_word_zero ls rs L) as MZ. unfold wz in MZ.
  destruct (lzeqb (zbytes ls) (zbytes rs)) eqn:E.
  - apply Z.eqb_eq. apply (proj2 MZ). apply lzeqb_eq in E.
    clear MZ. revert rs L E. induction ls as [|a ls IH]; intros [|c rs] L E; cbn in *; try reflexivity; try discriminate.
    injection E as E1 E2. f_equal; [apply bv_eq; exact E1 | apply IH; [lia | exact E2]].
  - apply Z.eqb_neq. intros C. apply (proj1 MZ) in C. subst rs.
    rewrite (proj2 (lzeqb_eq _ _) eq_refl) in E. discriminate.
Qed.

Lemma zbytes_cons : forall b bs, zbytes (b :: bs) = zb b :: zbytes bs. Proof. reflexivity. Qed.

Lemma length_1 : forall {X} (l : list X), length l = 1%nat -> exists x, l = [x].
Proof. intros X [|x [|y l]] H; cbn in H; try lia. exists x. reflexivity. Qed.
Lemma length_pos_cons : forall {X} (l : list X), (1 <= length l)%nat -> exists x l', l = x :: l'.
Proof. intros X [|x l] H; cbn in H; [lia|]. exists x, l. reflexivity. Qed.

Lemma signed_lit_small : forall z, 0 <= z < 2^63 -> bv_signed (Z_to_bv 64 z) = z.
Proof. intros z Hz. rewrite bv_signed_small by (rewrite unsigned_lit by lia; lia). apply unsigned_lit. lia. Qed.

