Definition litb (L : list Z) : list byte := map b8 L.
Lemma length_litb : forall L, length (litb L) = length L. Proof. intros. apply length_map. Qed.

(* [comment removed for export] *)
Definition vlit_okb (AL : Z * list Z) : bool :=
  ro_bytes_b asegs (fst AL) (litb (snd AL))
  && aglobb (fst AL) (Z.of_nat (length (snd AL)))
  && (0x26a80 <=? fst AL) && (fst AL + Z.of_nat (length (snd AL)) <=? 0x26e40)
  && (if list_eq_dec Z.eq_dec (zbytes (litb (snd AL))) (snd AL) then true else false).
Lemma VLITS_ok : forallb vlit_okb VLITS = true.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.eq); constr:(@Stdlib.Lists.List.forallb); constr:(@Corelib.Init.Datatypes.prod); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Datatypes.list); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_P_verb.vlit_okb); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_P_verb_stmt.VLITS)|] Array.empty "##)###-#'#(#,#&#-#+#*#.#/#)#VFCDUGEVHE#WI#JKWLC#Dm$'##"). Qed.

