Ltac open_verb CTX PURE :=
  lazymatch type of CTX with verb_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR0 & FR & WIN & ST & MU & WM & MI & SD);
  destruct PURE as (P64 & LO & CEIL & SEPW & SPAL & SHI & IMW);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPW; hydeL SPAL;
  unfold ASTRING_TO_VERB_STACK, ABCMP_STACK in *
  end.

(* [comment removed for export] *)
Ltac verb_rebuild_ctx m sp P :=
  try match goal with C : verb_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR0 : rw_cells _ mx (bv_unsigned sp + -48) [CB 8 ?j8],
    FR : rw_cells _ mx (bv_unsigned sp + -40) [C8 (_ ?p'); C8 (_ ?n'); C8 ?s1v; C8 ?s0v; C8 ?rav], WIN : bytes_at _ mx P ?bs,
    ST : stk _ mx ?lo _, MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : verb_side m _ ?shi _ _ |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : verb_ctx m mx sp s0v s1v rav j8 P bs p' n' lo shi)
        by (unfold verb_ctx, wz; repeat (split; [eassumption|]); eassumption)
  end end.

(* [comment removed for export] *)
Ltac verb_names sp lo :=
  repeat match goal with H : ACONST _ |- _ => clear H end;
  try (lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + -40) _ |- _ => rename H into FR end);
  try (lazymatch goal with H : stk _ _ lo _ |- _ => rename H into ST end);
  try (lazymatch goal with H : mem_inv _ _ |- _ => rename H into MI end).

(* [comment removed for export] *)
Ltac vload W q k HBS :=
  lazymatch type of W with bytes_at _ ?mx ?P ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q W ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read asegs _ P bs (q - P) b (Z_to_bv 64 q) W N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR;
    rewrite HBS in N; replace (Z.to_nat (q - P)) with k in N by lia; cbn [nth_error] in N; injection N as ->
  end.

(* [comment removed for export] *)
Ltac vb_chk SD MU WM CEIL a :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AP := fresh "AP" in let v := fresh "v" in let V1 := fresh "V1" in let V2 := fresh "V2" in let RD := fresh "RD" in
    let w := fresh "w" in
    destruct (verb_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (_ & _ & AP & _);
    destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AP ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD);
    clear AP;
    zstep; zstep; step; clear RD;
    first [ rewrite (sxb_b8_small v) by (clear - V1; lia) | rewrite (zxb_b8_small v) by (clear - V1; lia) ];
    shchk_join V1 V2; intros w; clear V1 V2
  end.

(* [comment removed for export] *)
Ltac dtests :=
  cbn [zbytes map lzeqb andb orb negb L_CL L_ET L_ST L_PY L_VE L_OL L_T L_RACE L_BIND L_PORT L_LINK L_LOCK
       L_EARCH L_IND L_ECKOUT L_ELETE L_EAD L_NNECT L_PTIONS L_OTIFY L_INK L_UBSCRIBE L_OCK L_TCH L_RGE L_ALENDAR
       L_ACTIVITY L_OPPATCH L_SUBSCRIBE L_SEARCH L_OPFIND];
  repeat (match goal with
          | |- context [?x =? ?y] =>
              first [ rewrite (proj2 (Z.eqb_eq x y)) by lia
                    | rewrite (proj2 (Z.eqb_neq x y)) by lia
                    | destruct (Z.eqb_spec x y) ];
              cbn [andb orb negb]
          end);
  first [ reflexivity | lia | exfalso; lia ].

(* [comment removed for export] *)
Ltac veval HBS HC lem := rewrite HBS, zbytes_cons, HC, lem.
Ltac vlet :=
  repeat match goal with
  | K : zb ?b = _ |- context [zb ?b =? _] => rewrite K
  | K : zb ?b <> ?c |- context [zb ?b =? ?c] => rewrite (proj2 (Z.eqb_neq _ _) K)
  | K : ?c <> zb ?b |- context [zb ?b =? ?c] => rewrite (proj2 (Z.eqb_neq _ _) (not_eq_sym K))
  end; cbn [Z.eqb Pos.eqb].
Ltac veval2 HBS HC lem := rewrite HBS; rewrite ?zbytes_cons in *; rewrite HC, lem; cbv beta iota; vlet.
(* [comment removed for export] *)
Lemma len_zbytes : forall bs, length (zbytes bs) = length bs.
Proof. intros bs. unfold zbytes. apply length_map. Qed.
Ltac vlen r := rewrite ?(lzeqb_length r) by (rewrite len_zbytes; cbn; lia).

(* [comment removed for export] *)
Ltac vlit_in := unfold VLITS; repeat (first [ left; reflexivity | right ]).

(* [comment removed for export] *)
Ltac bcmp_cases KE :=
  if_cases KE; [ apply (proj1 (Bool.negb_true_iff _)) in KE | apply (proj1 (Bool.negb_false_iff _)) in KE ].
(* [comment removed for export] *)
Ltac bcmp_cases_eq KE := if_cases KE.

Section EXITS.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma verb_exit : forall (v : Z) rax a0x a1x a2x s1x ra sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (j8 : list byte) (F : bvmap 5 word) fc (m m1 : mem) (P : Z) (bs : list byte) (p' n' lo shi : Z),
  verb_ctx m m1 sp s0v s1v ra j8 P bs p' n' lo shi -> verb_pure sp P bs lo shi ->
  v = verb_of (zbytes bs) ->
  evt asegs (string_to_verb_post ra sp gp tp s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs lo shi m)
