(* [comment removed for export] *)
Lemma verb_fail : forall rax a0x a1x a2x s0x s1x ra sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (j8 : list byte) (F : bvmap 5 word) fc (m m1 : mem) (P : Z) (bs : list byte) (p' n' lo shi : Z),
  verb_ctx m m1 sp s0v s1v ra j8 P bs p' n' lo shi -> verb_pure sp P bs lo shi ->
  verb_of (zbytes bs) = 0 ->
  evt asegs (string_to_verb_post ra sp gp tp s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs lo shi m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 s0x s1x a0x a1x a2x a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xb9e94) fc None m1 (seg_rom asegs)).
Proof.
  intros until shi. intros CTX PURE HV.
  (* [comment removed for export] *)
  step. eapply (verb_exit 0); [exact CTX | exact PURE | symmetry; exact HV].
Qed.

End EXITS.

(* [comment removed for export] *)
Ltac vfail CTX PURE tac := eapply verb_fail; [exact CTX | exact PURE | tac].
(* [comment removed for export] *)
Ltac vexit v CTX PURE tac := eapply (verb_exit v); [exact CTX | exact PURE | tac].
